const express = require('express');
const { createHandler } = require('graphql-http/lib/use/express');
const { buildSubgraphSchema } = require('@apollo/subgraph');
const gql = require('graphql-tag');

const app = express();
app.use(express.json());

const typeDefs = gql`
  type Workspace @key(fields: "id") {
    id: ID!
    name: String
    billingEmail: String
  }
`;

const resolvers = {
  Workspace: {
    __resolveReference: async (reference, context) => {
      // Ensure the requesting user is a member of the requested workspace
      return context.db.workspaces.findFirst({
        where: {
          id: reference.id,
          memberships: { some: { userId: context.user.id } }
        }
      });
    }
  }
};

const schema = buildSubgraphSchema({ typeDefs, resolvers });
app.all('/graphql', createHandler({ schema }));
module.exports = app;
